// Same file the browser fetches as /npa.json; generated by scripts/build-npa.mjs.
import rows from '../../../static/npa.json';
import { toPlace, type NpaRow, type Place } from '$lib/npa';

const table = new Map<number, Place>((rows as NpaRow[]).map((r) => [r[0], toPlace(r)]));

export const place = (npa: number) => table.get(npa);
export const isKnownNpa = (npa: number) => table.has(npa);
